#!/usr/bin/env bash
# LeanBCH verification gate — run locally or in CI.
# Enforces the guarantees that make this a *verified* library:
#   (1) the whole project builds (core VM + optimizer + necessity analyzer),
#   (2) ZERO `sorry`,
#   (3) axiom hygiene: no sorryAx / native_decide / ofReduceBool on the load-bearing theorems,
#   (4) the generated fold table is REPRODUCIBLE (tools/foldgen regenerates it byte-for-byte),
#   (5) the NECESSITY CLOSURE is stable: the transitive proof-term closure of the declared headlines
#       (Meta/necessity.json) is byte-identical to the committed baseline. A legal refactor never
#       changes WHICH declarations are load-bearing, so renaming/removing/re-attributing a load-bearing
#       decl changes it. NOTE: this gate is over the constant NAME-set + module attribution + axiom set;
#       it is BLIND to a pure numeric-literal / in-place term-value edit that preserves the name-set
#       (e.g. weakening a consensus limit). Those are pinned separately by the consensus-limit KATs in
#       LeanBCH/Validation/VM/Limits.lean — the closure gate is not the defense for literal values.
set -euo pipefail
export PATH="$HOME/.elan/bin:$PATH"
cd "$(dirname "$0")/../.."

echo "== [1/6] lake build (core VM + LeanBCHOpt + Validation + Meta analyzer) =="
BUILD=$(lake build 2>&1) || { echo "$BUILD"; echo "❌ BUILD FAILED (core)"; exit 1; }
BUILDOPT=$(lake build LeanBCHOpt 2>&1) || { echo "$BUILDOPT"; echo "❌ BUILD FAILED (LeanBCHOpt)"; exit 1; }
# The Validation layer must BUILD (so every extracted #eval/#guard/example actually executes).
BUILDVAL=$(lake build LeanBCHValidation 2>&1) || { echo "$BUILDVAL"; echo "❌ BUILD FAILED (LeanBCHValidation)"; exit 1; }
# Building Meta re-runs the necessity analyzer (a build-time reflection) → regenerates Meta/necessity.json.
BUILDMETA=$(lake build Meta 2>&1) || { echo "$BUILDMETA"; echo "❌ BUILD FAILED (Meta analyzer)"; exit 1; }
echo "$BUILDOPT" | tail -2

echo "== [2/6] zero-sorry check =="
if printf '%s\n%s\n%s\n' "$BUILD" "$BUILDOPT" "$BUILDMETA" | grep -q "declaration uses 'sorry'"; then
  printf '%s\n%s\n%s\n' "$BUILD" "$BUILDOPT" "$BUILDMETA" | grep "declaration uses 'sorry'"
  echo "❌ FAIL: 'sorry' present"; exit 1
fi
echo "✓ no sorry"

echo "== [3/6] axiom hygiene (analyzer-computed over ALL headlines + independent anchor) =="
# The necessity analyzer already computed the axiom footprint of the FULL headline set
# (Meta/Headlines.lean — the single source of truth) into Meta/necessity.json:
#   .axioms       = the union axiom set of every headline's proof-term closure
#   .headlineAxioms.<name> = per-headline footprint (missing headlines ⇒ .notFoundHeadlines nonempty)
# This SUBSUMES the old hand-maintained #print-axioms list (which drifted from Headlines.lean).
if command -v python3 >/dev/null 2>&1; then
  python3 - <<'PY' || exit 1
import json,sys
d=json.load(open("Meta/necessity.json"))
allowed={"propext","Quot.sound","Classical.choice"}
ax=set(d.get("axioms",[]))
nf=d.get("notFoundHeadlines",[])
bad=ax-allowed
if nf:  print("❌ FAIL: headline(s) missing from env (renamed/removed):",nf); sys.exit(1)
if bad: print("❌ FAIL: forbidden axiom in a headline's proof closure:",sorted(bad)); sys.exit(1)
print("✓ all",len(d.get("headlineAxioms",{})),"headlines resolve; axioms clean:",sorted(ax))
PY
else
  echo "⚠ python3 not found — skipping analyzer-based axiom check"
fi
# Independent anchor: two capstones checked directly via #print axioms, so an analyzer bug can't
# silently pass a dirty proof. (Deliberately tiny + hand-picked — NOT the source of truth.)
AXFILE="$(mktemp /tmp/leanbch_ax.XXXX.lean)"
cat > "$AXFILE" <<'EOF'
import LeanBCH.Opt.Core
import LeanBCH.VM.Invariants
#print axioms LeanBCH.Opt.schedule_refines
#print axioms LeanBCH.VM.verifyInput_cost_within_budget
EOF
AX=$(lake env lean "$AXFILE" 2>&1); rm -f "$AXFILE"
if echo "$AX" | grep -qiE 'sorryAx|native_decide|Lean\.ofReduceBool|unknown'; then
  echo "$AX"; echo "❌ FAIL: anchor #print axioms found a forbidden axiom / missing theorem"; exit 1
fi
echo "✓ independent anchor (schedule_refines + verifyInput_cost_within_budget) agrees"

echo "== [4/6] fold-table reproducibility (tools/foldgen regenerates byte-identically) =="
# LeanBCH/Opt/FoldTable.lean is GENERATED by tools/foldgen. Re-run the generator and diff against
# the checked-in table: they MUST be byte-identical, proving the committed table is exactly the
# generator output (no hand-edits). Skipped only when python3 is unavailable; CI has python3.
if command -v python3 >/dev/null 2>&1; then
  if PYTHONHASHSEED=0 python3 tools/foldgen/foldgen.py --check LeanBCH/Opt/FoldTable.lean; then
    echo "✓ FoldTable.lean is byte-identical to tools/foldgen output (reproducible)"
  else
    echo "❌ FAIL: LeanBCH/Opt/FoldTable.lean differs from tools/foldgen output"
    echo "   regenerate with: python3 tools/foldgen/foldgen.py > LeanBCH/Opt/FoldTable.lean"
    exit 1
  fi
else
  echo "⚠ python3 not found — skipping fold-table reproducibility gate"
fi

echo "== [5/6] necessity closure gate (Meta/necessity.json byte-identical to committed baseline) =="
# `lake build Meta` above re-ran the necessity analyzer, which OVERWRITES Meta/necessity.json with
# the freshly-computed transitive proof-term closure of Meta/Headlines.lean. If that file now differs
# from what is committed, the load-bearing set CHANGED — either a legal refactor's module-attribution
# update (regenerate + commit the new baseline after reviewing the diff), or an ACCIDENTAL change to
# what the headlines depend on (a keystone edit, a silently-dropped lemma). Either way: stop and look.
if command -v git >/dev/null 2>&1 && git rev-parse --git-dir >/dev/null 2>&1; then
  if git diff --exit-code -- Meta/necessity.json >/dev/null 2>&1; then
    echo "✓ necessity closure unchanged (load-bearing set stable)"
  else
    echo "❌ FAIL: Meta/necessity.json drifted from the committed baseline."
    echo "   The headline proof-term closure changed. Review the diff:"
    git --no-pager diff -- Meta/necessity.json | head -60
    echo "   If intentional (a file move / promoted headline), commit the regenerated baseline."
    exit 1
  fi
else
  echo "⚠ git unavailable — skipping necessity closure gate"
fi

# KAT-CONSERVATION gate: extracting a known-answer test from a model file into LeanBCH/Validation/*
# must MOVE it, never DROP it. The tree-wide assertion count (model + validation) must never fall
# below the committed baseline. Adding new KATs is fine (bump tools/health/kat-count.txt).
if command -v node >/dev/null 2>&1; then
  KAT_NOW=$(node tools/health/katcount.mjs)
  KAT_BASE=$(cat tools/health/kat-count.txt 2>/dev/null || echo 0)
  if [ "$KAT_NOW" -lt "$KAT_BASE" ]; then
    echo "❌ FAIL: KAT count dropped ($KAT_NOW < committed $KAT_BASE) — a known-answer test was lost."
    echo "   Compare: node tools/health/katcount.mjs --by-file"
    exit 1
  fi
  echo "✓ KAT conservation: $KAT_NOW build-time assertions (baseline $KAT_BASE)"
  # VACUITY LINT: the count gate is blind to a KAT neutered in place; reject the obvious insider
  # tautologies (example : True / single-line self-equality) so a real assertion can't be swapped for one.
  node tools/health/katcount.mjs --lint || { echo "❌ FAIL: a vacuous (assertion-free) KAT was found — see above."; exit 1; }
fi

echo "== [6/6] codebase-health map (REPORT ONLY — never fails the build in this draft) =="
# tools/health/map.mjs is a pure text/parse over LeanBCH/**/*.lean (no `lake build`). It regenerates
# tools/health/{REPORT.md,index.json} — the always-true "what exists / what's dead / what's
# duplicated" query surface (see tools/health/README.md). Report-only for now.
#
# NATURAL FAIL GATES TO PROMOTE LATER (intentionally NOT enforced here yet):
#   (a) real escape hatches — any sorry/admit/native_decide/partial in the map ⇒ this should exit 1
#       (it duplicates gate [2] for the un-kernel-checked layer but also catches partial/native_decide
#       structurally, not just via build warnings).
#   (b) new ORPHAN files — a .lean not reachable from a root is dead code ⇒ exit 1.
#   (c) artifact drift — `git diff --exit-code tools/health/` after regenerating ⇒ the committed
#       REPORT/index are stale (author forgot to regenerate) ⇒ exit 1.
if command -v node >/dev/null 2>&1; then
  node tools/health/map.mjs || echo "⚠ health map errored (report-only, not gating)"
  # TRUST_MANIFEST.md is regenerated from Meta/necessity.json + the health index (skeptic-facing;
  # committed + human-read). Report-only; the drift catch is the closure gate [5/6] upstream.
  node tools/manifest/gen.mjs || echo "⚠ trust-manifest generator errored (report-only, not gating)"
  # OPTIMIZER VM-INTERFACE gate (Phase 3): LeanBCH.Opt.* may reach the core ONLY through the small
  # allowed seam (VM.{Straightline,RunStraight,Instr,Extended}, Cost.Arith) — the boundary that
  # survives the leanbch-opt package split. A new cross-import is a design regression → FAIL.
  OPTVIOL=$(python3 -c "import json;print(json.load(open('tools/health/index.json'))['summary']['optInterfaceViolations'])" 2>/dev/null || echo 0)
  if [ "$OPTVIOL" != "0" ]; then
    echo "❌ FAIL: $OPTVIOL optimizer→VM cross-import(s) outside the allowed interface:"
    python3 -c "import json;[print('   ',v['from'],'⇒',v['imports']) for v in json.load(open('tools/health/index.json'))['optInterface']['violations']]" 2>/dev/null
    exit 1
  fi
  echo "✓ optimizer VM-interface contract: 0 violations (Opt reaches the VM only through the allowed seam)"
else
  echo "⚠ node not found — skipping health map + trust manifest (report-only)"
fi

echo "✅ ALL CHECKS PASS — LeanBCH is 0-sorry, axiom-clean, fold-table-reproducible, closure-stable"
echo "   (health map regenerated — see tools/health/REPORT.md; not a gate yet, see [6/6] comment)"
